SELECT 

FROM swm_alarm_light a

WHERE a.id = #{id}

SELECT 
	,
	(SELECT COUNT(1) FROM swm_alarm_light_config c WHERE c.light_id = a.id AND c.status = '0') AS config_count
FROM swm_alarm_light a


	a.status = #{STATUS_NORMAL}

		AND a.light_name LIKE CONCAT('%', #{lightName}, '%')


		AND a.sn_code LIKE CONCAT('%', #{snCode}, '%')


		AND a.enable_alarm = #{enableAlarm}




		ORDER BY ${page.orderBy}


		ORDER BY a.update_date DESC

SELECT 

FROM swm_alarm_light a


	a.status = #{STATUS_NORMAL}



		ORDER BY ${page.orderBy}


		ORDER BY a.update_date DESC

